    	LOGGER.info("handling DeleteCouponEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Coupon entity = delete( event.getCouponId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
