    /**
     * Method to retrieve the Coupon via an CouponPrimaryKey.
     * @param 	id Long
     * @return 	Coupon
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Coupon handle( FindCouponQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCouponId() );
    }
    
    /**
     * Method to retrieve a collection of all Coupons
     *
     * @param	query	FindAllCouponQuery 
     * @return 	List<Coupon> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Coupon> handle( FindAllCouponQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCoupon,
 * but only if the id matches
 *
 * @param		entity	Coupon
 */
	protected void emitFindCoupon( Coupon entity ) {
		LOGGER.info("handling emitFindCoupon" );
		
	    queryUpdateEmitter.emit(FindCouponQuery.class,
	                            query -> query.getFilter().getCouponId().equals(entity.getCouponId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCoupon
	 * 
	 * @param		entity	Coupon
	 */
	protected void emitFindAllCoupon( Coupon entity ) {
		LOGGER.info("handling emitFindAllCoupon" );
		
	    queryUpdateEmitter.emit(FindAllCouponQuery.class,
	                            query -> true,
	                            entity);
	}

